UPDATE rent
SET board_game_id = #{boardGameId},
board_game_item_id = #{boardGameItemId},
rented_at = NOW()
WHERE room_number = #{roomNumber}
AND status = 'rent';


INSERT INTO rent (board_game_id, board_game_item_id, room_number)
SELECT #{boardGameId}, #{boardGameItemId}, #{roomNumber}
WHERE NOT EXISTS (
SELECT 1 FROM rent WHERE room_number = #{roomNumber} AND status = 'rent'
);

