SELECT COUNT(*)
  FROM rent
 WHERE room_number   = #{roomNumber}
   AND board_game_id = #{boardGameId}
   AND returned_at IS NULL

SELECT room_number
FROM room_rfid
WHERE controller_id = #{controllerId}
AND rfid = #{rfid}
